export class AdversarialToolTesting {
  constructor() {
    this.testCases = [];
  }

  addTestCase(testCase) {
    this.testCases.push(testCase);
  }

  runTests(tool) {
    return this.testCases.map(test => {
      try {
        return { test, result: test(tool) };
      } catch (error) {
        return { test, error };
      }
    });
  }
}

// Example usage
const adversarialTesting = new AdversarialToolTesting();
adversarialTesting.addTestCase(tool => tool.run() === 'expectedOutput');
const tool = { run: () => 'unexpectedOutput' };
const results = adversarialTesting.runTests(tool);
console.log(results);